pub fn token_ok(given: &[u8; TOKEN_LEN], configured: &[u8; TOKEN_LEN]) -> bool {
    let mut diff: u8 = 0;
    let mut any: u8 = 0;
    let mut i = 0;
    while i < TOKEN_LEN {
        diff |= given[i] ^ configured[i];
        any |= configured[i];
        i += 1;
    }
    diff == 0 && any != 0
}

