pub fn begin(current: Session, authorised: bool, has_length: bool, len: u32) -> Option<Session> {
    if !current.active && authorised && has_length && len > 0 && len <= ACTIVE_SIZE {
        Some(Session { active: true, declared: len, written: 0 })
    } else {
        None
    }
}

