chunk.kernel_code:
pub fn chunk(s: Session, n: u32) -> Option<(u32, Session)> {
    if s.active && n > 0 && n <= s.declared - s.written {
        Some((s.written, Session { active: true, declared: s.declared, written: s.written + n }))
    } else {
        None
    }
}

